//! Icebreaker FO.4: the forest (« Forêt », jalon FO,
//! `docs/icebreaker/PLAN-FORET.md`). Its shape (clearings, trails, platforms,
//! bridges) is a grid of blocks generated by `icebreaker-foret`, the same code
//! as the workshop page; here it is placed in the world, on a levelled ground.

use super::{butin::Butin, grotte::Inhabitant};
use icebreaker_foret::{Foret, Formes, Genre, debout, grille, marcher};
use rand::{RngExt, SeedableRng};
use rand_chacha::ChaCha8Rng;
use serde::Deserialize;
use std::collections::HashSet;
use vek::*;

/// `assets/icebreaker/forets/foret.ron`.
#[derive(Clone, Debug, Deserialize)]
pub struct Settings {
    /// Chunks kept around the middle of the forest, on each side.
    pub emprise: i32,
    pub couleurs: Couleurs,
    /// Icebreaker FO.5: who lives here (Q66: our six species only, one per
    /// forest), and the files of its enemies.
    pub population: Population,
    pub habitants: Vec<String>,
    /// Those of a « nid » clearing, and those of the platforms.
    pub meute: Vec<String>,
    pub tireurs: Vec<String>,
    pub chef: String,
    pub especes: Vec<String>,
    /// The loot by distance (`butin.ron`), read by `load`.
    #[serde(skip)]
    pub butin: Option<Butin>,
    /// The shapes (`formes.ron`), read by `load`.
    #[serde(skip)]
    pub formes: Option<Formes>,
    /// Icebreaker DF: the line of the difficulty of the expedition (`difficulte.ron`), set by `load` (the one
    /// of the launcher, or the default one) and by the party that leaves.
    #[serde(skip)]
    pub difficulte: common::icebreaker_difficulte::Niveau,
}

/// Icebreaker FO.5: how many live in the forest, and where the chests lie.
#[derive(Clone, Debug, Deserialize)]
pub struct Population {
    /// Enemies of a « camp » clearing, of a « nid » one, and around the chief
    /// (min, max).
    pub camp: (i32, i32),
    pub nid: (i32, i32),
    pub garde: (i32, i32),
    /// Share of the platforms walked to that hold a shooter.
    pub guetteurs: f32,
    /// Share of the huts and of the ends of branches that hold a chest.
    pub coffres_hauts: f32,
    /// No one and no chest within this many blocks of where one arrives.
    pub calme: i32,
    /// The chest sprite.
    pub coffre: String,
}

/// The colour of each kind of block.
#[derive(Clone, Debug, Deserialize)]
pub struct Couleurs {
    pub tronc: (u8, u8, u8),
    pub racine: (u8, u8, u8),
    pub feuilles: (u8, u8, u8),
    pub planche: (u8, u8, u8),
    pub rambarde: (u8, u8, u8),
    pub buisson: (u8, u8, u8),
    pub herbe: (u8, u8, u8),
    pub sentier: (u8, u8, u8),
    pub clairiere: (u8, u8, u8),
    pub sente: (u8, u8, u8),
}

impl Settings {
    pub fn load() -> Result<Self, String> {
        let read = |name: &str| {
            let path = common::assets::ASSETS_PATH.join("icebreaker/forets").join(name);
            std::fs::read_to_string(&path).map_err(|e| format!("{} : {e}", path.display()))
        };
        let mut settings: Self = ron::from_str(&read("foret.ron")?).map_err(|e| format!("foret.ron illisible : {e}"))?;
        if settings.emprise < 3 {
            return Err("foret.ron : emprise d'au moins 3 tronçons".into());
        }
        if settings.habitants.is_empty() || settings.meute.is_empty() || settings.tireurs.is_empty() || settings.chef.is_empty() {
            return Err("foret.ron : habitants, meute, tireurs (au moins un chacun) et chef".into());
        }
        if let Some(espece) = settings.especes.iter().find(|e| e.parse::<common::npc::NpcBody>().is_err()) {
            return Err(format!("foret.ron : espèce inconnue « {espece} »"));
        }
        settings.butin = Some(Butin::load()?);
        settings.formes = Some(Formes::lire(&read("formes.ron")?)?);
        settings.difficulte = common::icebreaker_difficulte::niveau(None);
        Ok(settings)
    }
}

/// A generated forest, placed in the world.
#[derive(Clone)]
pub struct Lieu {
    pub foret: Foret,
    /// The block (0, 0, 0) of its grid: the middle of the forest, the lowest
    /// block over its ground.
    pub origine: Vec3<i32>,
    /// The profile of `formes.ron` it was drawn with, and its seed.
    pub profil: String,
    pub seed: u64,
    pub summary: String,
    /// Icebreaker FO.5: who lives here (the chief in the clearing at the end),
    /// their species, the chests and the tier of the loot of each.
    pub inhabitants: Vec<Inhabitant>,
    pub species: Option<String>,
    /// Icebreaker DF: the line of its difficulty (`difficulte.ron`).
    pub difficulte: common::icebreaker_difficulte::Niveau,
    pub chests: Vec<Vec3<i32>>,
    pub chest_tiers: Vec<usize>,
    pub chest: String,
    pub butin: Option<Butin>,
}

impl Lieu {
    fn local(&self, wpos: Vec3<i32>) -> Vec3<i32> { wpos - self.origine }

    /// What the block is (`icebreaker_foret::grille`): air out of the forest.
    pub fn bloc(&self, wpos: Vec3<i32>) -> u8 {
        let p = self.local(wpos);
        self.foret.grille.bloc(p.x, p.y, p.z)
    }

    /// The lowest block over the ground of a column of the forest.
    pub fn sol(&self, wpos: Vec2<i32>) -> Option<i32> {
        let p = wpos - self.origine.xy();
        let z = self.foret.grille.sol(p.x, p.y);
        (z != i32::MAX).then_some(z + self.origine.z)
    }

    /// What the ground of a column is (grass, trail, clearing).
    pub fn nature(&self, wpos: Vec2<i32>) -> u8 {
        let p = wpos - self.origine.xy();
        self.foret.grille.nature(p.x, p.y)
    }

    /// The blocks of the forest, in the world.
    pub fn bounds(&self) -> Aabb<i32> {
        let g = &self.foret.grille;
        Aabb {
            min: self.origine + Vec3::from(g.min),
            max: self.origine + Vec3::from(g.max()),
        }
    }

    /// Where one arrives: the clearing at the edge, a block one stands in.
    pub fn arrival(&self) -> Vec3<i32> { self.origine + Vec3::from(self.foret.depart) }

    /// Icebreaker FO.9: the lanterns and the lianas: each block and what it is.
    pub fn decors(&self) -> Vec<(Vec3<i32>, u8)> {
        self.foret
            .grille
            .pleins()
            .filter(|(_, bloc)| matches!(*bloc, grille::LANTERNE | grille::LIANE))
            .map(|(p, bloc)| (self.origine + Vec3::from(p), bloc))
            .collect()
    }

    /// The ladders: each block, and the side its trunk is on.
    pub fn echelles(&self) -> Vec<(Vec3<i32>, Vec2<i32>)> {
        let g = &self.foret.grille;
        g.pleins()
            .filter(|(_, bloc)| *bloc == grille::ECHELLE)
            .map(|(p, _)| {
                let vers = [(1, 0), (0, 1), (-1, 0), (0, -1)]
                    .into_iter()
                    .find(|(dx, dy)| g.bloc(p[0] + dx, p[1] + dy, p[2]) == grille::BOIS)
                    .unwrap_or((1, 0));
                (self.origine + Vec3::from(p), Vec2::from(vers))
            })
            .collect()
    }
}

/// Blocks kept between the forest and the edge of its area, for the leaves
/// (the margin of the grid of `icebreaker-foret`).
const MARGE: f32 = 16.0;

/// The forest of `seed` around `origine` (the lowest block over the ground,
/// which the site levels). `voulu`: the profile asked for, drawn by the seed
/// otherwise.
pub fn generate(settings: &Settings, seed: u64, origine: Vec3<i32>, voulu: Option<&str>) -> Result<Lieu, String> {
    let formes = settings.formes.as_ref().ok_or("formes.ron pas lu")?;
    let (nom, forme) = formes.tirer(seed, voulu);
    let mut forme = forme.clone();
    forme.emprise = forme.emprise.min(settings.emprise as f32 * 32.0 - MARGE);
    let foret = icebreaker_foret::generer(&forme, seed, &|_, _| 0);
    let (habitants, coffres) = peupler(settings, &foret, seed);
    let species = super::races::species_of(&settings.especes, seed).cloned();
    // The loot gets richer with the distance to the arrival (`butin.ron`).
    let butin = settings.butin.clone();
    let depart = Vec3::from(foret.depart);
    let loin = |p: Vec3<i32>| (p - depart).xy().as_::<f32>().magnitude();
    let plus_loin = habitants.iter().map(|h| h.0).chain(coffres.iter().copied()).map(loin).fold(1.0, f32::max);
    let niveau = |p: Vec3<i32>| (loin(p) / plus_loin * (NIVEAUX - 1) as f32) as usize;
    let palier = |p: Vec3<i32>| butin.as_ref().map_or(1, |b| b.palier(niveau(p), NIVEAUX));
    let inhabitants: Vec<Inhabitant> = habitants
        .into_iter()
        .map(|(p, asset, chief)| Inhabitant {
            pos: origine + p,
            level: niveau(p) as i32,
            loot: butin.as_ref().map(|b| b.creature(if chief { "chief" } else { "" }, palier(p)).to_string()),
            asset,
            chief,
        })
        .collect();
    let chest_tiers = coffres.iter().map(|p| palier(*p)).collect();
    let summary = format!(
        "forêt « {nom} », graine {seed} : {}, race {}, {} habitant(s), {} coffre(s)",
        foret.resume,
        species.as_deref().unwrap_or("aucune"),
        inhabitants.len(),
        coffres.len(),
    );
    Ok(Lieu {
        foret,
        origine,
        profil: nom.to_string(),
        seed,
        summary,
        inhabitants,
        species,
        difficulte: settings.difficulte.clone(),
        chests: coffres.into_iter().map(|p| origine + p).collect(),
        chest_tiers,
        chest: settings.population.coffre.clone(),
        butin,
    })
}

/// Parts the distance to the arrival is cut in, for the loot.
const NIVEAUX: usize = 100;

/// Icebreaker FO.5: who lives in the forest and where its chests lie, in
/// blocks of its grid: (the block the feet are in, the entity, the chief) and
/// the blocks of the chests. The chief and his guards in the clearing at the
/// end, a group in each other clearing, shooters on the platforms; a chest in
/// each clearing, some in the huts and at the end of the branches. Everything
/// is walked to from the arrival, and nothing lies near it.
fn peupler(settings: &Settings, foret: &Foret, seed: u64) -> (Vec<(Vec3<i32>, String, bool)>, Vec<Vec3<i32>>) {
    let pop = &settings.population;
    let g = &foret.grille;
    let pieds = marcher(g, foret.depart);
    let depart = Vec3::from(foret.depart);
    let mut rng = ChaCha8Rng::seed_from_u64(seed.wrapping_mul(0x2545_F491_4F6C_DD1D).wrapping_add(66));
    let mut pris: HashSet<Vec3<i32>> = HashSet::new();
    let mut habitants = Vec::new();
    let mut coffres = Vec::new();

    // A free block one stands in, walked to, away from the arrival.
    let libre = |p: Vec3<i32>, pris: &HashSet<Vec3<i32>>| {
        g.bloc(p.x, p.y, p.z) == grille::AIR
            && debout(g, p.x, p.y, p.z)
            && pieds.contient(g, p.into_array())
            && (p - depart).as_::<f32>().magnitude() >= pop.calme as f32
            && !pris.contains(&p)
    };
    // Such a block between `pres` and `rayon` blocks of `centre`, at its height (`sol`: on the
    // ground of its column); `dessous`: what the feet are on, if it matters.
    let autour = |centre: Vec3<i32>, pres: f32, rayon: f32, sol: bool, dessous: Option<u8>, rng: &mut ChaCha8Rng, pris: &HashSet<Vec3<i32>>| {
        (0..40).find_map(|_| {
            let (a, d) = (rng.random_range(0.0..std::f32::consts::TAU), rng.random_range(pres.powi(2)..=rayon.max(pres).powi(2)).sqrt());
            let (x, y) = (centre.x + (d * a.cos()).round() as i32, centre.y + (d * a.sin()).round() as i32);
            let p = Vec3::new(x, y, if sol { g.sol(x, y) } else { centre.z });
            (libre(p, pris) && dessous.is_none_or(|b| g.bloc(p.x, p.y, p.z - 1) == b)).then_some(p)
        })
    };
    let tirer = |liste: &[String], rng: &mut ChaCha8Rng| liste[rng.random_range(0..liste.len())].clone();

    for (i, c) in foret.clairieres.iter().enumerate() {
        let centre = Vec3::from(c.centre);
        let (groupe, parmi, rayon) = match c.genre {
            Genre::Arrivee => continue,
            Genre::Fond => (pop.garde, &settings.habitants, 6.0),
            Genre::Camp => (pop.camp, &settings.habitants, c.rayon as f32 - 2.0),
            Genre::Nid => (pop.nid, &settings.meute, 4.0),
        };
        // The chief stands in the middle of his clearing, whatever is near.
        if i == foret.fond() && pris.insert(centre) {
            habitants.push((centre, settings.chef.clone(), true));
        }
        // Icebreaker DF: more or fewer of them, as the difficulty says.
        let groupe = rng.random_range(groupe.0..=groupe.1.max(groupe.0));
        let groupe = settings.difficulte.effectif(groupe, || rng.random());
        for _ in 0..groupe {
            if let Some(p) = autour(centre, 0.0, rayon.max(3.0), true, None, &mut rng, &pris) {
                pris.insert(p);
                habitants.push((p, tirer(parmi, &mut rng), false));
            }
        }
        if let Some(p) = autour(centre, 0.0, (c.rayon as f32 - 2.0).max(3.0), true, None, &mut rng, &pris) {
            pris.insert(p);
            coffres.push(p);
        }
    }

    // The shooters, on the planks of the platforms, out of the trunk (a
    // hollow one has a floor inside too).
    for arbre in &foret.arbres {
        for (z, atteint) in arbre.niveaux.iter().zip(&arbre.atteints) {
            if !*atteint || !rng.random_bool(f64::from((pop.guetteurs * settings.difficulte.nombre).clamp(0.0, 1.0))) {
                continue;
            }
            let centre = Vec3::new(arbre.pied[0], arbre.pied[1], *z);
            if let Some(p) = autour(centre, arbre.rayon as f32 + 1.5, arbre.plateforme as f32 - 1.0, false, Some(grille::PLANCHE), &mut rng, &pris) {
                pris.insert(p);
                habitants.push((p, tirer(&settings.tireurs, &mut rng), false));
            }
        }
    }

    // The chests up in the trees: at the back of the huts, at the end of the
    // branches that stop short.
    let cabanes = foret.cabanes.iter().filter(|h| h.atteinte).map(|h| {
        let centre = Vec3::from(h.centre);
        let fond = centre + Vec3::new(h.cote.0, h.cote.1, 0);
        if libre(fond, &pris) { fond } else { centre }
    });
    let bouts = foret.perchoirs.iter().map(|p| Vec3::new(p.b[0].round() as i32, p.b[1].round() as i32, p.b[2] as i32));
    for p in cabanes.chain(bouts).collect::<Vec<_>>() {
        if rng.random_bool(f64::from(pop.coffres_hauts.clamp(0.0, 1.0))) && libre(p, &pris) {
            pris.insert(p);
            coffres.push(p);
        }
    }
    (habitants, coffres)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The files of the game are read, and every profile gives a forest one
    /// walks whole, within the area kept for it.
    #[test]
    fn every_profile_fits_and_is_walked() {
        let settings = Settings::load().unwrap();
        let origine = Vec3::new(2048, 2048, 200);
        let moitie = settings.emprise * 32;
        for nom in settings.formes.as_ref().unwrap().profils.keys() {
            let lieu = generate(&settings, 5, origine, Some(nom)).unwrap();
            assert_eq!(&lieu.profil, nom);
            assert!(lieu.foret.praticable, "{}", lieu.summary);
            let b = lieu.bounds();
            assert!(b.min.x >= origine.x - moitie && b.max.x <= origine.x + moitie, "{nom} : {b:?}");
            // One stands where one arrives, on the ground of the clearing.
            let a = lieu.arrival();
            assert_eq!(lieu.sol(a.xy()), Some(a.z));
            assert_eq!(lieu.nature(a.xy()), grille::CLAIRIERE);
            assert_eq!(lieu.bloc(a), grille::AIR);
        }
    }

    /// Icebreaker FO.5: one chief in the clearing at the end, a single species
    /// (Q66), shooters up on the planks; everyone and every chest stands on
    /// something, away from the arrival, no two at the same place.
    #[test]
    fn the_forest_is_inhabited() {
        let settings = Settings::load().unwrap();
        let origine = Vec3::new(2048, 2048, 200);
        let calme = settings.population.calme as f32;
        for nom in settings.formes.as_ref().unwrap().profils.keys() {
            for seed in 1..=4 {
                let lieu = generate(&settings, seed, origine, Some(nom)).unwrap();
                let qui = format!("{nom}, graine {seed}");
                let chefs: Vec<&Inhabitant> = lieu.inhabitants.iter().filter(|i| i.chief).collect();
                assert_eq!(chefs.len(), 1, "{qui} : un seul chef");
                let fond = &lieu.foret.clairieres[lieu.foret.fond()];
                assert_eq!(chefs[0].pos, origine + Vec3::from(fond.centre), "{qui}");
                assert_eq!(chefs[0].asset, settings.chef);
                assert_eq!(chefs[0].loot.as_ref(), Some(&settings.butin.as_ref().unwrap().chef));
                assert!(settings.especes.contains(lieu.species.as_ref().expect("une espèce")));

                let mut places = HashSet::new();
                let a = lieu.arrival();
                for pos in lieu.inhabitants.iter().map(|i| i.pos).chain(lieu.chests.iter().copied()) {
                    assert_eq!(lieu.bloc(pos), grille::AIR, "{qui} : {pos:?}");
                    let au_sol = lieu.sol(pos.xy()) == Some(pos.z);
                    assert!(au_sol || lieu.bloc(pos - Vec3::unit_z()) != grille::AIR, "{qui} : {pos:?} sur le vide");
                    assert!(places.insert(pos), "{qui} : deux en {pos:?}");
                    assert!((pos - a).as_::<f32>().magnitude() >= calme, "{qui} : {pos:?} près de l'arrivée");
                }
                assert!(lieu.inhabitants.len() >= 6, "{qui} : {}", lieu.summary);
                assert_eq!(lieu.chests.len(), lieu.chest_tiers.len());
                assert!(lieu.chests.len() >= lieu.foret.clairieres.len() - 2, "{qui} : {}", lieu.summary);

                // The shooters stand on the planks, over the ground.
                let hauts: Vec<&Inhabitant> = lieu
                    .inhabitants
                    .iter()
                    .filter(|i| lieu.bloc(i.pos - Vec3::unit_z()) == grille::PLANCHE)
                    .collect();
                assert!(!hauts.is_empty(), "{qui} : personne en hauteur ({})", lieu.summary);
                assert!(hauts.iter().all(|i| settings.tireurs.contains(&i.asset)), "{qui}");
                // ...out of the trunks: they see the ground.
                let dehors = |p: Vec3<i32>| {
                    lieu.foret.arbres.iter().all(|t| (p - origine - Vec3::from(t.pied)).xy().as_::<f32>().magnitude() > t.rayon as f32)
                };
                assert!(hauts.iter().all(|i| dehors(i.pos)), "{qui} : un tireur dans un tronc");
                // On the ground, only the people of the clearings.
                assert!(lieu.inhabitants.iter().all(|i| i.chief || settings.habitants.contains(&i.asset) || settings.meute.contains(&i.asset)));
            }
        }
        // Same seed, same people; the loot gets richer away from the arrival.
        let lieu = generate(&settings, 2, origine, Some("passerelles")).unwrap();
        let encore = generate(&settings, 2, origine, Some("passerelles")).unwrap();
        assert_eq!(lieu.summary, encore.summary);
        assert!(lieu.inhabitants.iter().zip(&encore.inhabitants).all(|(a, b)| a.pos == b.pos && a.asset == b.asset));
        let loin = |p: Vec3<i32>| (p - lieu.arrival()).xy().as_::<f32>().magnitude();
        for (i, a) in lieu.chests.iter().enumerate() {
            for (j, b) in lieu.chests.iter().enumerate() {
                assert!(loin(*a) > loin(*b) || lieu.chest_tiers[i] <= lieu.chest_tiers[j]);
            }
        }
        // Every enemy named in the data is an entity of the game.
        use common::assets::AssetExt;
        let people = settings.habitants.iter().chain(&settings.meute).chain(&settings.tireurs).chain([&settings.chef]);
        for asset in people {
            common::assets::Ron::<common::generation::EntityConfig>::load(asset).unwrap_or_else(|e| panic!("{asset} : {e}"));
        }
    }
    // Icebreaker DF: more and more people from difficulty 1 to 6, in the same forests.
    #[test]
    fn the_difficulty_changes_how_many_live_there() {
        let mut settings = Settings::load().unwrap();
        let difficultes = common::icebreaker_difficulte::IcebreakerDifficulte::actuel();
        let origine = Vec3::new(2048, 2048, 200);
        let mut totaux = Vec::new();
        for n in 1..=6 {
            settings.difficulte = difficultes.niveau(Some(n));
            let lieux: Vec<Lieu> = (1..=6).map(|seed| generate(&settings, seed, origine, Some("immense")).unwrap()).collect();
            assert!(lieux.iter().all(|l| l.difficulte.numero == n && l.inhabitants.iter().filter(|i| i.chief).count() == 1));
            totaux.push(lieux.iter().map(|l| l.inhabitants.len()).sum::<usize>());
        }
        assert!(totaux.windows(2).all(|w| w[0] < w[1]), "{totaux:?}");
        assert!(2 * totaux[5] > 3 * totaux[0], "{totaux:?}");
    }
}
